This is the function I use for it. It works for any number of nesting levels with no issues:
JavaScript:
TLB.SKABase.parseParameters = function(parameters, destination) {
    for (const param in parameters) {
        const value = parameters[param];
        if (value.length > 0 && !isNaN(value)) {
            if (Math.floor(value) === value) destination[param] = parseInt(value);
            else destination[param] = parseFloat(value);
        } else if (value.length > 0) {
            try {
                destination[param] = JSON.parse(value);
                TLB.SKABase.parseParameters(destination[param], destination[param]);
            } catch (e) {
                destination[param] = value;
            }
        }
    }
};

I understand. I use this parsing in my plugin.
Spoiler:
Parsing
JavaScript:
function SafeParse(json) {
    try {
        if (json != null && json)
            return JSON.parse(json);
        return null;
    } catch (e) {
        console.error(`Error parsing JSON data ${e}`);
        return null;
    }
}
Then I use class constructors. I feel more comfortable this way: I describe the structure once and forget about it.
But the problem I'm talking about is related to the editor itself. The rpgmz interface refuses to display my nested structure correctly.
